// Des: Doctor: read-only check that the buttons and boxes each job needs are on the live pages
// Flo: Chrome version check > for each job open its page (read-only) > look for the first label the job needs > print found or MISSING > exit 3 when anything is missing
// I/O: Ctx + optional job name + optional url (caller) > printed table; error Drift when a label is missing
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const pack = @import("ut-loca-pack.zig");
const Probe = struct { name: []const u8, src: jobs.Src, key: []const u8, role: []const u8, need_url: bool = false };
const EXTRA = [_]Probe{ .{ .name = "post", .src = .home, .key = "post_open", .role = "button" }, .{ .name = "reply", .src = .noti, .key = "repl_btnz", .role = "button" }, .{ .name = "renew", .src = .mark_sell, .key = "mark_renw", .role = "button" }, .{ .name = "sold", .src = .mark_sell, .key = "mark_sold", .role = "button" } };
fn roleOf(tpl: jobs.T) []const u8 { if (tpl.role.len > 0) return tpl.role; return switch (tpl.op) { .typez, .clear => "textbox", .toggle => "checkbox", else => "button" }; }
fn firstLabeled(job: *const jobs.Job) ?jobs.T { for (job.steps) |tpl| { if (tpl.key.len > 0 and tpl.op != .expect and tpl.op != .hand and tpl.op != .stopif) return tpl; } return null; }
fn check(ctx: *task.Ctx, name: []const u8, path: []const u8, key: []const u8, role: []const u8, miss: *u32, okay: *u32) !void { try task.visit(ctx, path); ctx.page.arm(ctx.conf.brow_time_seco * 1000); const labs = pack.lab(ctx.conf, key); var found = (try ctx.page.axFind(ctx.aren, role, labs, 0)) != null; if (!found and std.mem.eql(u8, role, "checkbox")) found = (try ctx.page.axFind(ctx.aren, "switch", labs, 0)) != null; if (found) { okay.* += 1; task.say(ctx, "OK      {s}: {s} ({s})", .{ name, key, role }); } else { miss.* += 1; task.say(ctx, "MISSING {s}: {s} ({s}) on {s}", .{ name, key, role, path }); } }
fn chromeMajor(ctx: *task.Ctx) u32 { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const res = ctx.page.call(ctx.aren, "Browser.getVersion", "") catch return 0; if (res != .object) return 0; const pro = res.object.get("product") orelse return 0; if (pro != .string) return 0; const at = std.mem.findScalar(u8, pro.string, '/') orelse return 0; var end = at + 1; while (end < pro.string.len and pro.string[end] >= '0' and pro.string[end] <= '9') end += 1; return std.fmt.parseInt(u32, pro.string[at + 1 .. end], 10) catch 0; }
pub fn doctor(ctx: *task.Ctx, only: []const u8, urlz: []const u8) !u32 { var miss: u32 = 0; var okay: u32 = 0; const maj = chromeMajor(ctx); if (maj > 0) { if (maj < ctx.conf.brow_vers_minz) { miss += 1; task.say(ctx, "MISSING browser: Chrome {d} is older than brow_vers_minz {d}", .{ maj, ctx.conf.brow_vers_minz }); } else task.say(ctx, "OK      browser: Chrome {d}", .{maj}); } for (&jobs.JOBS) |*jb| { if (only.len > 0 and !std.mem.eql(u8, jb.name, only)) continue; if (jb.steps[0].soft) continue; const tpl = firstLabeled(jb) orelse continue; if (jb.src == .url and urlz.len == 0) { if (only.len > 0) task.say(ctx, "SKIP    {s}: needs --url", .{jb.name}); continue; } if (jb.src == .dmsg_thre and urlz.len == 0) continue; const path = try jrun.pathOf(ctx, .{ .url = urlz, .to = if (urlz.len > 0) urlz else "1" }, jb.src, jb.pkey); try check(ctx, jb.name, path, tpl.key, roleOf(tpl), &miss, &okay); } for (&EXTRA) |*pr| { if (only.len > 0 and !std.mem.eql(u8, pr.name, only)) continue; const path = try jrun.pathOf(ctx, .{}, pr.src, ""); try check(ctx, pr.name, path, pr.key, pr.role, &miss, &okay); } task.say(ctx, "doctor: {d} ok, {d} missing", .{ okay, miss }); if (miss > 0) return error.Drift; return okay; }
